values
  ('esabcc-o1-ghg-total', '{"columns":[{"header":"Value","source":"EEA GHG data viewer","formula":{"expr":"IF(A >= 2023, ROUND(([env_air_gge TOTXMEMO] + [env_air_gge CRF1D1A] + [env_air_gge CRF1D1B]), 1), ([International aviation]+[Energy supply]+[Industry]+[Transport]+[Buildings and agriculture energy]+[Agriculture (non-energy)]+[LULUCF]+[Waste and other sectors])+[International maritime]*(0.6374552000704592))"}},{"header":"International aviation","source":"EEA GHG data viewer","formula":{"expr":"[1.D.1.a - International Aviation]/1000"}},{"header":"Energy supply","source":"EEA GHG data viewer","formula":{"expr":"([1.A.1 - Energy Industries]+[1.B - Fugitive Emissions from Fuels])/1000"}},{"header":"Industry","source":"EEA GHG data viewer","formula":{"expr":"([1.A.2 - Manufacturing Industries and Construction]+[2 - Industrial Processes and Product Use])/1000"}},{"header":"Transport","source":"EEA GHG data viewer","formula":{"expr":"([1.A.3 - Transport])/1000"}},{"header":"Buildings and agriculture energy","source":"EEA GHG data viewer","formula":{"expr":"[1.A.4 - Other Sectors]/1000"}},{"header":"Agriculture (non-energy)","source":"EEA GHG data viewer","formula":{"expr":"[3 - Agriculture]/1000"}},{"header":"LULUCF","source":"EEA GHG data viewer","formula":{"expr":"[4 - Land Use, Land-Use Change and Forestry]/1000"}},{"header":"Waste and other sectors","source":"EEA GHG data viewer","formula":{"expr":"[Total net emissions (UNFCCC)]/1000-[LULUCF]-[Agriculture (non-energy)]-[Buildings and agriculture energy]-[Transport]-[Industry]-[Energy supply]"}},{"header":"International maritime","source":"EEA GHG data viewer","formula":{"expr":"[1.D.1.b - International Navigation]/1000"}},{"header":"1.D.1.a - International Aviation","source":"EEA GHG data viewer"},{"header":"1.A.1 - Energy Industries","source":"EEA GHG data viewer"},{"header":"1.B - Fugitive Emissions from Fuels","source":"EEA GHG data viewer"},{"header":"1.A.2 - Manufacturing Industries and Construction","source":"EEA GHG data viewer"},{"header":"2 - Industrial Processes and Product Use","source":"EEA GHG data viewer"},{"header":"1.A.3 - Transport","source":"EEA GHG data viewer"},{"header":"1.A.4 - Other Sectors","source":"EEA GHG data viewer"},{"header":"3 - Agriculture","source":"EEA GHG data viewer"},{"header":"4 - Land Use, Land-Use Change and Forestry","source":"EEA GHG data viewer"},{"header":"Total net emissions (UNFCCC)","source":"EEA GHG data viewer"},{"header":"1.D.1.b - International Navigation","source":"EEA GHG data viewer"},{"header":"env_air_gge TOTXMEMO","source":"Eurostat env_air_gge · geo=EU27_2020, unit=MIO_T, freq=A, airpol=GHG, src_crf=TOTXMEMO · https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/env_air_gge?format=JSON&lang=EN&geo=EU27_2020&unit=MIO_T&freq=A&airpol=GHG&src_crf=TOTXMEMO"},{"header":"env_air_gge CRF1D1A","source":"Eurostat env_air_gge · geo=EU27_2020, unit=MIO_T, freq=A, airpol=GHG, src_crf=CRF1D1A · https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/env_air_gge?format=JSON&lang=EN&geo=EU27_2020&unit=MIO_T&freq=A&airpol=GHG&src_crf=CRF1D1A"},{"header":"env_air_gge CRF1D1B","source":"Eurostat env_air_gge · geo=EU27_2020, unit=MIO_T, freq=A, airpol=GHG, src_crf=CRF1D1B · https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/env_air_gge?format=JSON&lang=EN&geo=EU27_2020&unit=MIO_T&freq=A&airpol=GHG&src_crf=CRF1D1B"}],"rows":[{"year":2005,"cells":[4393.8544455997635,96.09354678675581,1489.2308635829077,981.2737567577378,847.3858950621939,665.0392409976354,389.22393811242966,-342.10947613129105,169.72820383495673,153.7182167242595,96093.5467867558,1383791.909747243,105438.95383566488,556523.7994334318,424749.957324306,847385.8950621939,665039.2409976354,389223.9381124297,-342109.47613129107,4199772.422216571,153718.2167242595,null,null,null]},{"year":2006,"cells":[4392.775467577483,101.16153164168031,1494.1525158714342,973.7864643499324,855.4935985864113,663.4478326795688,386.0797416515591,-351.